"Solicita eliminar permanentemente tu cuenta de Drex y tus datos":"Demande la suppression définitive de votre compte Drex et de vos données",
"Cómo solicitar la eliminación":"Comment demander la suppression",
"Para proteger tus datos, necesitamos una solicitud formal para procesar eliminaciones de cuenta. Sigue estos pasos:":"Pour protéger tes données, nous avons besoin d'une demande formelle pour traiter les suppressions de compte. Suis ces étapes :",
"PASO 1":"ÉTAPE 1",
"PASO 2":"ÉTAPE 2",
"PASO 3":"ÉTAPE 3",
"Envía un correo desde tu dirección de correo registrada en Drex a":"Envoie un e-mail depuis ton adresse e-mail enregistrée sur Drex à",
"Usa este asunto:":"Utilise cet objet :",
"\"Solicitud de eliminación de cuenta - [Tu nombre de usuario]\"":"\"Demande de suppression de compte - [Votre nom d'utilisateur]\"",
"Nuestro equipo de soporte verificará tu identidad y procesará la eliminación en un plazo de 7 días hábiles.":"Notre équipe d'assistance vérifiera votre identité et traitera la suppression dans un délai de 7 jours ouvrables.",
"Enviar correo de solicitud":"Envoyer l'e-mail de demande",
"¿Qué datos se eliminan?":"Quelles données sont supprimées ?",
"Cuando se procese tu solicitud, la siguiente información se eliminará permanentemente de nuestros servidores activos:":"Lorsque votre demande sera traitée, les informations suivantes seront définitivement supprimées de nos serveurs actifs :",
"Tu información de perfil (correo, nombre de usuario, bio, foto de perfil).":"Vos informations de profil (e-mail, nom d'utilisateur, bio, photo de profil).",
"Todas tus publicaciones y comentarios públicos en la comunidad Drex.":"Toutes tes publications et tous tes commentaires publics dans la communauté Drex.",
"Tu historial de votos e interacciones sociales.":"Ton historique de votes et d'interactions sociales.",
"Tu tarjeta digital Drex Bank y tu historial de transacciones.":"Votre carte numérique Drex Bank et votre historique de transactions.",
"Nota: algunos datos de transacciones pueden conservarse por un periodo limitado según lo exijan regulaciones financieras u obligaciones legales.":"Remarque : certaines données de transactions peuvent être conservées pendant une durée limitée, conformément aux réglementations financières ou obligations légales.",
"Conservación de datos":"Conservation des données",
"Una vez eliminados, tus datos no se pueden recuperar. Mantenemos una copia de seguridad de 30 días como periodo de gracia por seguridad antes del borrado final de nuestros sistemas. Después de este periodo, todos los identificadores personales se eliminan o se anonimizan por completo.":"Une fois supprimées, tes données ne peuvent pas être récupérées. Nous conservons une copie de sauvegarde de 30 jours comme période de grâce de sécurité avant la suppression définitive de nos systèmes. Après cette période, tous les identifiants personnels sont complètement supprimés ou anonymisés.",
