"Drex podrá eliminar cualquier canción que infrinja derechos de autor y suspender mi acceso a la función de música en caso de reincidencia.":"Drex pourra supprimer toute chanson qui enfreint les droits d'auteur et suspendre mon accès à la fonction musique en cas de récidive.",
