"No entendí la hora. Toca una opción o escríbela (p. ej. «mañana a las 9»).":"Je n'ai pas compris l'heure. Touche une option ou écris-la (par ex. « demain à 9h »).",
"No entendí los pasos de la rutina. Sepáralos con comas, por ejemplo: «crea mi rutina de noche: ver borradores, revisar notificaciones».":"Je n'ai pas compris les étapes de la routine. Sépare-les par des virgules, par exemple : « crée ma routine de nuit : voir les brouillons, vérifier les notifications ».",
